-- crash-edit/persons
-- The people recorded for a crash, killed first then injured, in the order they were added.
--
-- Parameters, with the example values used to render this file:
--   $1 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

select "id", "crash_id", "slug", "status", "name_en", "name_np", "age", "sex", "road_user", "hometown_text", "name_visibility", "publication", "version", "created_at", "updated_at"
from "persons"
where "persons"."crash_id" = $1
order by case "persons"."status" when 'killed' then 0 when 'injured' then 1 else 2 end, "persons"."created_at", "persons"."id";
